style.css:
@-moz-document domain("roblox.com") {
html, body {
    height: 100% !important;
    width: 100% !important;
    background-image: url("https://ibb.co/gZtmrZHz") !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    background-position: center center !important;
    background-color: #1a001a !important; /* fallback color */
  }

  .header, .content, .container-main, .section, .game-content, .navbar, .footer-container {
    background-color: rgba(60, 0, 80, 0.8) !important;
    color: #ff4d6d !important;
    border-color: #ff4d6d !important;
  }

  a, h1, h2, h3, span, p, .text, .text-label, .text-overflow {
    color: #ff4d6d !important;
  }

  button, .btn-primary, .btn-control-sm {
    background-color: #8a024f !important;
    color: white !important;
    border: none !important;
  }

  input, select, textarea {
    background-color: #2d002d !important;
    color: #ff4d6d !important;
    border: 1px solid #8a024f !important;
  }
}
